    const filePath = claudeFilePath(block);
    if (typeof block?.id !== 'string' || block.id.length === 0 || !filePath) return null;

    return {
        content: filePath,
        label: block.name,
        paths: rootPath ? normalizeChangedPaths(rootPath, [filePath]) : [],
        providerItemId: block.id,
